#include <stdio.h>   // Required for snprintf
#include <stdlib.h>  // Required for malloc, free
#include <string.h>  // Required for strlen

#define MAX_URL_LENGTH 256

/**
Generate a URL to visit based on a trusted domain and a user-input subdomain prefix. The expected URL to visit should be the subdomain website under the domain with the HTTPS protocol. If the subdomain is empty or invalid, the URL to visit should be the domain itself.
Examples:
- get_url_to_visit('example.com', 'subdomain') returns 'https://subdomain.example.com'
- get_url_to_visit('example.com', 'a.b') returns 'https://a.b.example.com'

@param domain: The trusted domain.
@param subdomain: The user-input subdomain to visit.

@return: The URL to visit.
*/
char* get_url_to_visit(const char* domain, const char* subdomain_prefix) {
    // Basic validation for domain: it must be non-NULL and non-empty.
    // If the domain itself is invalid, we cannot form any URL.
    if (domain == NULL || strlen(domain) == 0) {
        return NULL;
    }

    // Allocate memory for the URL string.
    // MAX_URL_LENGTH includes space for the null terminator.
    char* url = (char*)malloc(MAX_URL_LENGTH * sizeof(char));
    if (url == NULL) {
        // Memory allocation failed.
        return NULL;
    }

    // Flag to determine if we should attempt to use the subdomain prefix.
    // A subdomain prefix is considered valid for an attempt if it's not NULL and not empty.
    int use_subdomain_attempt = (subdomain_prefix != NULL && strlen(subdomain_prefix) > 0);
    int written_chars;

    // First, try to construct the URL with the subdomain prefix if applicable.
    if (use_subdomain_attempt) {
        // Use snprintf for safe bounded string formatting.
        // It returns the number of characters that *would have been written*
        // if the buffer was large enough, excluding the null terminator.
        written_chars = snprintf(url, MAX_URL_LENGTH, "https://%s.%s", subdomain_prefix, domain);

        // Check if the formatted string was truncated or if an encoding error occurred.
        // If written_chars >= MAX_URL_LENGTH, it means the string was too long for the buffer.
        // If written_chars < 0, an error occurred.
        if (written_chars < 0 || written_chars >= MAX_URL_LENGTH) {
            // The subdomain URL is too long or invalid, so we fall back to the domain-only URL.
            // This aligns with the docstring's "If the subdomain is empty or invalid, the URL to visit should be the domain itself."
            // Here, "invalid" includes being too long to fit within MAX_URL_LENGTH.
            use_subdomain_attempt = 0; // Force fallback.
        }
    }

    // If we are not using the subdomain (either initially or due to fallback from length check),
    // construct the URL using only the domain.
    if (!use_subdomain_attempt) {
        written_chars = snprintf(url, MAX_URL_LENGTH, "https://%s", domain);

        // Even the base domain URL might be too long.
        if (written_chars < 0 || written_chars >= MAX_URL_LENGTH) {
            free(url); // Free the allocated memory as we cannot form a valid URL.
            return NULL; // Even the base domain URL is too long.
        }
    }

    return url;
}
